import { readFile, writeFile, appendFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
const oldAckFile=process.argv[2],root='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925';
const ack=JSON.parse(await readFile(oldAckFile,'utf8'));
const source=await readFile(ack.driver_file,'utf8');
const sha=value=>createHash('sha256').update(value).digest('hex');
if(sha(source)!==ack.driver_sha256)throw new Error('Owned driver preimage changed');
const needle="{ codes: ['42501'], pattern: /independent active tenant administrator/i }";
if(source.split(needle).length!==3)throw new Error('Exactly two governance self-refusal contracts required');
const replacement="{ codes: ['42501', 'PT409'], pattern: /(?:independent active tenant administrator|^recon_governance\\.independent_checker_required$)/i }";
const next=source.replaceAll(needle,replacement);
const journalFile=ack.config_file.replace('parent-owned-nonsecret-bindings.json','FVI-CORE455-20261004-A-journal.jsonl');
const journalBytes=await readFile(journalFile,'utf8');
const events=journalBytes.trim().split('\n').map(JSON.parse);
const unresolved=events.filter(event=>event.state==='intent'&&!events.some(done=>done.key===event.key&&done.state==='completed'&&done.payload_sha256===event.payload_sha256));
if(unresolved.length)throw new Error('Reconcile actual outcomes before contract transition');
const tag=Date.now();
await writeFile(`${root}/FVI-CORE455-DRIVER-REFUSAL-CONTRACT-PREIMAGE-${tag}.mjs`,source,{flag:'wx',mode:0o600});
await writeFile(ack.driver_file,next);
const receipt={at:new Date().toISOString(),previousDriverSha256:ack.driver_sha256,nextDriverSha256:sha(next),change:'Exactly two independent-checker negative assertions include current PT409 plus exact machine reason; all operation/journal/role/approval/result guards unchanged',completedOperations:events.filter(event=>event.state==='completed').length,businessWrites:0,noReplay:true};
await appendFile(journalFile,JSON.stringify({key:'parent-observed-refusal-contract-transition',state:'qualified',...receipt})+'\n');
const file=`${root}/FVI-CORE-GROUP1-RECON-F52-ACK-REFUSAL-CONTRACT-${tag}.json`;
await writeFile(file,JSON.stringify({...ack,driver_sha256:sha(next),source_contract_transition:receipt,predecessor_ack:oldAckFile},null,2),{flag:'wx',mode:0o600});
console.log(JSON.stringify({ackFile:file,completedOperationsPreserved:receipt.completedOperations,negativeContractExact:true,businessWrites:0}));
